import { 
  MeshBasicNodeMaterial,
  PlaneGeometry,
  Mesh,
  Group,
  Vector2,
  Vector3
} from 'three/webgpu';
import {
  texture,
  uv,
  vec2,
  uniform,
  mix,
  positionWorld,
  cameraPosition,
  normalize,
  dot,
  smoothstep,
  normalWorld,
  transformNormal,
  add,
  sub,
  mul,
  float,
  positionLocal
} from 'three/tsl';
import { gsap } from 'gsap';

// TSL displacement helper
const displacementMap = (depthTex, strength = 0.15) => {
  const depthUv = uv().mul(vec2(1, 1));
  const depth = texture(depthTex, depthUv).r;
  return positionLocal.add(normalWorld.mul(depth.sub(0.5)).mul(strength));
};

export default function createNode(config, ctx) {
  const group = new Group();
  const colors = config.intent?.visualSpec?.colors || config.colors || {};
  const paper = colors.paper || '#e8ecf2';
  const accent = colors.accent || '#ff2a38';
  const surface = colors.surface || '#0b0b10';

  // --- Parallax Card ---
  const geometry = new PlaneGeometry(1.4, 0.35, 64, 64);

  // Displacement material with TSL
  const depthTex = uniform(0);
  let material;

  const setupMaterial = async () => {
    const [tex, depth] = await Promise.all([
      ctx.textureLoader.loadTexture(config.imageUrl),
      ctx.textureLoader.loadTexture(config.depthMapUrl)
    ]);

    depthTex.value = depth;

    material = new MeshBasicNodeMaterial({
      color: paper,
      transparent: true,
      opacity: 0.95
    });

    // TSL displacement
    const displacedPos = displacementMap(depthTex, 0.12);
    geometry.displacePosition = displacedPos;

    // Parallax offset based on camera
    const parallaxOffset = uniform(new Vector2(0, 0));
    const baseUv = uv();
    const parallaxUv = vec2(
      baseUv.x.add(parallaxOffset.x),
      baseUv.y.add(parallaxOffset.y)
    );

    material.colorNode = texture(tex, parallaxUv);
    geometry.computeVertexNormals();

    // Update UVs for parallax
    material.needsUpdate = true;

    // Cleanup uniform references
    material.userData = { parallaxOffset };
  };

  setupMaterial();

  const mesh = new Mesh(geometry, material);
  mesh.position.z = 0.05;
  group.add(mesh);

  // --- Center Jewel ---
  const jewelGeo = new PlaneGeometry(0.08, 0.08);
  const jewelMat = new MeshBasicNodeMaterial({
    color: accent,
    transparent: true,
    opacity: 0.9
  });
  const jewel = new Mesh(jewelGeo, jewelMat);
  jewel.position.set(0, 0, 0.1);
  group.add(jewel);

  // --- Thin Rule Lines ---
  const ruleMat = new MeshBasicNodeMaterial({
    color: paper,
    transparent: true,
    opacity: 0.4
  });

  const leftRule = new Mesh(new PlaneGeometry(0.5, 0.008), ruleMat);
  leftRule.position.set(-0.35, 0, 0.08);
  group.add(leftRule);

  const rightRule = new Mesh(new PlaneGeometry(0.5, 0.008), ruleMat);
  rightRule.position.set(0.35, 0, 0.08);
  group.add(rightRule);

  // --- Contact Shadow ---
  const shadowGeo = new PlaneGeometry(1.6, 0.5);
  const shadowMat = new MeshBasicNodeMaterial({
    color: surface,
    transparent: true,
    opacity: 0.3
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -0.02, -0.02);
  group.add(shadow);

  // --- Interactions ---
  let isHovered = false;
  let interactionTimeline = null;

  const handleHover = () => {
    if (interactionTimeline) interactionTimeline.kill();
    interactionTimeline = gsap.timeline();

    interactionTimeline.to(mesh.position, {
      y: 0.15,
      duration: 0.4,
      ease: 'power2.out'
    })
    .to(jewel.material, {
      opacity: 1,
      duration: 0.3,
      ease: 'power2.out'
    }, 0)
    .to(ruleMat, {
      opacity: 0.6,
      duration: 0.3,
      ease: 'power2.out'
    }, 0);
  };

  const handleHoverOut = () => {
    if (interactionTimeline) interactionTimeline.kill();
    interactionTimeline = gsap.timeline();

    interactionTimeline.to(mesh.position, {
      y: 0,
      duration: 0.5,
      ease: 'power3.out'
    })
    .to(jewel.material, {
      opacity: 0.9,
      duration: 0.3,
      ease: 'power2.out'
    }, 0)
    .to(ruleMat, {
      opacity: 0.4,
      duration: 0.3,
      ease: 'power2.out'
    }, 0);
  };

  const handleClick = () => {
    if (interactionTimeline) interactionTimeline.kill();
    interactionTimeline = gsap.timeline();

    interactionTimeline.to(mesh.scale, {
      x: 0.97,
      y: 0.97,
      duration: 0.12,
      ease: 'back.out(1.7)'
    })
    .to(mesh.scale, {
      x: 1,
      y: 1,
      duration: 0.3,
      ease: 'power4.out'
    })
    .then(() => {
      ctx.emit('hub-features.select');
    });
  };

  // Attach event handlers
  group.userData.handlers = {
    hover: handleHover,
    hoverOut: handleHoverOut,
    click: handleClick
  };

  // Cleanup
  group.userData.cleanup = () => {
    if (interactionTimeline) interactionTimeline.kill();
    geometry.dispose();
    jewelMat.dispose();
    ruleMat.dispose();
    shadowMat.dispose();
    if (material) {
      material.dispose();
    }
  };

  // Initial subtle float
  gsap.to(group.position, {
    y: 0.02,
    duration: 2,
    ease: 'sine.inOut',
    yoyo: true,
    repeat: -1
  });

  return group;
}
